"""Canonical SHA-256 of a synthetic dataset's arrays (shared by harness and tests)."""

from __future__ import annotations

import hashlib
from collections.abc import Sequence

import numpy as np
import pandas as pd

FLOAT_COLUMNS = ("x1", "x2", "x3", "x4", "x5", "x6", "time", "event_time", "censoring_time")
# Original parquet column names -> package names.
LEGACY_NAMES = {"duration": "time", "censor_time": "censoring_time"}
CENSORING_ID = {"E1": "C0", "E2": "C0", "E3": "C0", "E4": "C1", "H1": "C1H"}
SEEDS = (101, 202, 303, 404, 505, 606, 707, 808, 909, 1010)


def legacy_filename(scenario: str, seed: int) -> str:
    """File name of one dataset generated by the original synthetic study."""
    cid = CENSORING_ID[scenario]
    return f"dataset__scenario-{scenario}__baseline-B1__censoring-{cid}__seed-{seed}.parquet"


def dataset_summary(splits: Sequence[pd.DataFrame]) -> dict[str, list[float]]:
    """Platform-robust summary of train, validation and test, in order.

    Per split: the event count, then the sum and the sum of squares of every
    float column. Compared at ``[SYNTH_summary]``, unlike the bit-exact
    :func:`dataset_digest`, so last-bit linear-algebra differences between
    machines do not fail it while any change to the generator's logic does.
    """
    out: dict[str, list[float]] = {}
    for name, frame in zip(("train", "validation", "test"), splits, strict=True):
        frame = frame.rename(columns=LEGACY_NAMES)
        values = [float(frame["event"].to_numpy(dtype="<i8").sum())]
        for col in FLOAT_COLUMNS:
            x = frame[col].to_numpy(dtype="<f8")
            values += [float(x.sum()), float((x * x).sum())]
        out[name] = values
    return out


def dataset_digest(splits: Sequence[pd.DataFrame]) -> str:
    """Hash train, validation and test in order: float columns as <f8, event as <i8."""
    h = hashlib.sha256()
    for frame in splits:
        frame = frame.rename(columns=LEGACY_NAMES)
        for col in FLOAT_COLUMNS:
            h.update(np.ascontiguousarray(frame[col].to_numpy(dtype="<f8")).tobytes())
        h.update(np.ascontiguousarray(frame["event"].to_numpy(dtype="<i8")).tobytes())
    return h.hexdigest()
